  /// Institutions of a given [type], sorted alphabetically.
  static List<Institution> byType(InstitutionType type) {
    final List<Institution> list =
        all.where((Institution i) => i.type == type).toList()
          ..sort((Institution a, Institution b) => a.name.compareTo(b.name));
    return list;
  }

  /// Free-text search, optionally narrowed by [type], [state] or [ownership].
  static List<Institution> search(
    String query, {
    InstitutionType? type,
    String? state,
    Ownership? ownership,
  }) {
    Iterable<Institution> results = all;
    if (type != null) {
      results = results.where((Institution i) => i.type == type);
    }
    if (state != null && state.isNotEmpty) {
      results = results.where((Institution i) => i.state == state);
    }
    if (ownership != null) {
      results = results.where((Institution i) => i.ownership == ownership);
    }
    if (query.trim().isNotEmpty) {
      results = results.where((Institution i) => i.matches(query));
    }
    final List<Institution> list = results.toList()
      ..sort((Institution a, Institution b) => a.name.compareTo(b.name));
    return list;
  }

  static Institution? byName(String name) {
    for (final Institution i in all) {
      if (i.name == name) return i;
    }
    return null;
  }

  static int countOf(InstitutionType type) =>
      all.where((Institution i) => i.type == type).length;
}
